import {BOOK_GROUPS,BOOK_INFO,UNIT,LESSON_SCENES,TOPICS,THEOLOGIAN_DEMOS,DEFAULT_THEOLOGIAN,PRACTICE_ITEMS} from './data.js';

const main=document.querySelector('#prototype-main');
const storeKey='canonical-shelf-v7-prototype-state';
const defaultState={direction:'A',page:'home',scene:0,selectedBook:'Genesis',topic:'covenant',practiceIndex:0,practiceOrder:[...PRACTICE_ITEMS[0].options],practiceSelected:'',practiceFeedback:'',lessonFeedback:'',theologianQuestion:'',theologianResult:null,chat:[]};
let state=loadState();

function loadState(){try{return {...defaultState,...JSON.parse(localStorage.getItem(storeKey)||'{}')}}catch{return {...defaultState}}}
function saveState(){localStorage.setItem(storeKey,JSON.stringify(state))}
function esc(v=''){return String(v).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]))}
function setState(patch,{save=true}={}){state={...state,...patch};if(save)saveState();render()}
function directionName(){return state.direction==='A'?'Living Library':state.direction==='B'?'Scholarly Folio':'Scripture Atlas'}
function pageTitle(){return ({home:'Home',learn:'Learn',lesson:'Lesson',practice:'Practice',bible:'Bible',topics:'Topics',theologian:'Theologian'})[state.page]}
function groupForBook(title){return BOOK_GROUPS.find(g=>g.books.includes(title))}
function bookDetails(title){const g=groupForBook(title);return BOOK_INFO[title]||{subtitle:`${g?.name||'Biblical'} book in the canonical library`,era:title==='Acts'?'Early Christian movement':'Canonical and historical context varies by passage',genre:g?.name==='Wisdom'?'Poetry / wisdom':g?.name.includes('Prophets')?'Prophetic literature':g?.name.includes('Letters')?'Letter':g?.name==='Gospels'?'Gospel':'Biblical literature',key:`Explore ${title} through literary shape, historical setting, themes, and cross-references.`,question:`What changes when ${title} is read in its literary and historical context?`}}
function lessonStatusIcon(s){return s==='complete'?'✓':s==='current'?'▶':'○'}
function statusText(s){return s==='complete'?'Complete':s==='current'?'Current':'Locked'}
function progress(){return `<div class="progress" aria-label="33 percent complete"><span style="width:33%"></span></div>`}
function metrics(){return `<div class="grid grid-4"><div class="metric"><b>33%</b><span>Unit 1 progress</span></div><div class="metric"><b>25</b><span>Scored units</span></div><div class="metric"><b>139</b><span>Scored activities</span></div><div class="metric"><b>45</b><span>Curated Topics</span></div></div>`}
function unitLessonsCards(){return UNIT.lessons.map(l=>`<div class="lesson-row ${l.status==='current'?'current':''}"><div class="lesson-index">${esc(l.n)}</div><div><b>${esc(l.title)}</b><div class="meta">${esc(l.kind)} · ${l.minutes} min · ${statusText(l.status)}</div></div>${l.status==='current'?`<button class="button" data-page="lesson">Continue</button>`:`<span class="meta">${lessonStatusIcon(l.status)}</span>`}</div>`).join('')}
function syllabusRows(){return UNIT.lessons.map(l=>`<tr class="${l.status==='current'?'current':''}"><td>${esc(l.n)}</td><td><b>${esc(l.title)}</b><div class="meta">${esc(l.kind)} · ${l.minutes} min</div></td><td class="status">${statusText(l.status)} ${lessonStatusIcon(l.status)}</td></tr>`).join('')}

function render(){
  document.body.dataset.direction=state.direction;
  document.querySelectorAll('[data-direction-choice]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.directionChoice===state.direction)));
  document.querySelectorAll('.prototype-nav [data-page]').forEach(b=>{if(b.dataset.page===state.page)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});
  const renderer={home:renderHome,learn:renderLearn,lesson:renderLesson,practice:renderPractice,bible:renderBible,topics:renderTopics,theologian:renderTheologian}[state.page];
  main.innerHTML=renderer();
  main.focus({preventScroll:true});
  document.title=`${pageTitle()} — ${directionName()} — Canonical Shelf Prototype`;
}

function renderHome(){return state.direction==='A'?homeA():state.direction==='B'?homeB():homeC()}
function homeA(){return `<section class="page home-a"><div class="library-hero"><p class="eyebrow">Welcome back to your library</p><h1 class="display">Read deeply. Remember what matters.</h1><p class="lede">Canonical Shelf becomes a personal theological library: tactile, scholarly, guided, and built around the books themselves.</p><div class="library-actions"><button class="button" data-page="lesson">Continue lesson 1.2</button><button class="button secondary" data-page="bible">Open the shelf</button></div></div><aside class="panel resume-card"><p class="eyebrow">Your place</p><h3>The Story and Its Setting</h3><p class="meta">Unit 1 · Lesson 2 · Study Focus ready</p>${progress()}<div class="quick-list"><div class="quick-row"><span>▣</span><div><b>Review due</b><div class="meta">Memory & meaning · 5 questions</div></div><button class="button secondary" data-page="practice">Start</button></div><div class="quick-row"><span>✦</span><div><b>Theologian</b><div class="meta">Ask, compare, examine evidence</div></div><button class="button secondary" data-page="theologian">Ask</button></div><div class="quick-row"><span>⌂</span><div><b>Topics</b><div class="meta">45 unscored reference articles</div></div><button class="button secondary" data-page="topics">Browse</button></div></div></aside></section><section class="page"><div class="section-head"><div><p class="eyebrow">Library state</p><h2 class="section-title">Your shelf remembers the journey.</h2></div><p>Progress, retention, Scripture, references, and private study remain distinct but connected.</p></div>${metrics()}</section>`}
function homeB(){return `<section class="page"><div class="home-b"><div class="folio-hero"><p class="eyebrow">Bible literacy for thoughtful adults</p><h1 class="display">Read with context. Think with clarity. Apply with care.</h1><p class="lede">A guided course, a complete Bible reference, active practice, and an evidence-aware theological research companion.</p><div class="library-actions"><button class="button" data-page="lesson">Continue learning</button><button class="button secondary" data-page="bible">Explore the Bible</button></div></div><aside class="panel folio-aside"><p class="eyebrow">Current work</p><h2>The Story and Its Setting</h2><p>Lesson 2 of 5</p>${progress()}<p class="meta">One review item is due today.</p></aside></div><div class="folio-home-sections"><section><div class="section-head"><div><p class="eyebrow">Pick up where you left off</p><h2 class="section-title">Continue deliberately.</h2></div></div><div class="grid grid-2"><div class="panel panel-pad"><b>Lesson 1.2</b><h3>The Story and Its Setting</h3><p class="meta">7 min · context, chronology, interpretation</p><button class="button" data-page="lesson">Continue</button></div><div class="panel panel-pad"><b>Review due</b><h3>Memory & meaning</h3><p class="meta">5 retrieval questions · ~3 min</p><button class="button secondary" data-page="practice">Practice</button></div></div></section><aside>${metrics()}</aside></div></section>`}
function homeC(){const phases=['Story','Order','Groups','Chronology','Content','Themes','Verses'];return `<section class="page home-c"><div class="atlas-hero"><p class="eyebrow">Your place in the biblical world</p><h1 class="display">See the whole story. Know where you are.</h1><p class="lede">Course, Bible, Topics, Practice, and Theologian become connected views of one structured learning world.</p><div class="library-actions"><button class="button" data-page="lesson">Resume current scene</button><button class="button secondary" data-page="learn">View journey</button></div></div><div class="journey-strip">${phases.map((p,i)=>`<div class="journey-node"><b>${p}</b><span>${i===0?'Active':'Units '+(i*3+1)+'–'+(i*3+3)}</span></div>`).join('')}</div><div class="grid grid-3"><div class="panel panel-pad"><p class="eyebrow">Current coordinate</p><h2>The Story and Its Setting</h2>${progress()}<button class="button" data-page="lesson">Enter lesson</button></div><div class="panel panel-pad"><p class="eyebrow">Next retrieval</p><h2>Memory & meaning</h2><p class="meta">Due now · estimated 3 minutes</p><button class="button secondary" data-page="practice">Practice</button></div><div class="panel panel-pad"><p class="eyebrow">Explore a question</p><h2>Theologian</h2><p class="meta">Text → context → interpretations → position</p><button class="button secondary" data-page="theologian">Ask</button></div></div></section>`}

function renderLearn(){return state.direction==='A'?learnA():state.direction==='B'?learnB():learnC()}
function learnA(){return `<section class="page learn-a"><aside class="panel unit-ledger"><p class="eyebrow">Course volumes</p><h2>25 integrated units</h2><ol>${['Start Here','The Story','Order & Groups','Chronology','Content','Themes','Verses'].map((x,i)=>`<li class="${i<2?'active':''}"><button type="button"><b>${i===0?'Orientation':`Phase ${i}`}</b><br><span class="meta">${x}</span></button></li>`).join('')}</ol></aside><article class="panel course-volume"><div class="section-head"><div><p class="eyebrow">Volume I · Unit 1</p><h1 class="section-title">The Story and Its Setting</h1><p>${UNIT.subtitle}</p></div><div><b style="font-size:32px">33%</b>${progress()}</div></div><div class="panel panel-pad" style="background:var(--surface2)"><b>Purpose</b><p>Learn to distinguish the biblical story from the historical worlds in which its texts were written, heard, collected, and interpreted.</p></div><div class="lesson-path">${unitLessonsCards()}</div></article></section>`}
function learnB(){return `<section class="page learn-b"><article class="syllabus"><p class="eyebrow">Course · Unit 1 of 25</p><h1 class="section-title">The Story and Its Setting</h1><p class="lede">Understand the big picture. See how the Bible fits into real history, people, places, genres, and communities.</p><div class="divider"></div><table class="syllabus-table"><thead><tr><th>Activity</th><th>Title</th><th>Status</th></tr></thead><tbody>${syllabusRows()}</tbody></table></article><aside class="course-margin"><div class="panel"><p class="eyebrow">Unit progress</p><b style="font-size:36px">33%</b>${progress()}</div><div class="panel"><b>Study resources</b><p class="meta">Timeline · key terms · maps · sources</p></div><div class="panel"><b>Retention</b><p class="meta">1 item due today · next interval 3 days</p><button class="button secondary" data-page="practice">Review now</button></div></aside></section>`}
function learnC(){return `<section class="page learn-c"><div class="atlas-course-head"><div class="panel panel-pad"><p class="eyebrow">Journey coordinate · Unit 1</p><h1 class="section-title">The Story and Its Setting</h1><p class="lede">A guided route through story, people, places, chronology, literary form, and interpretation.</p></div><div class="panel panel-pad"><b style="font-size:38px">33%</b><p class="meta">Unit explored</p>${progress()}</div></div><div class="panel path-map"><p class="eyebrow">Learning path</p><div class="path-line">${UNIT.lessons.map((l,i)=>`<div class="path-stop ${l.status==='current'?'current':''}"><button type="button" ${l.status==='current'?'data-page="lesson"':''}>${lessonStatusIcon(l.status)}</button><small>${esc(l.n)}<br>${esc(l.title)}</small></div>`).join('')}</div></div><div class="course-tools"><div class="tool-card"><b>Map</b><p class="meta">Places and political worlds</p></div><div class="tool-card"><b>Timeline</b><p class="meta">Canonical order vs chronology</p></div><div class="tool-card"><b>People</b><p class="meta">Communities and relationships</p></div><div class="tool-card"><b>Mastery</b><p class="meta">Reasoning and retention</p></div></div></section>`}

function lessonCheck(){return `<div class="knowledge-check"><b>Knowledge check</b><p>Which statement is an interpretation rather than direct textual observation?</p><label><input type="radio" name="lesson-check" value="a"> Romans 1 uses exchange language.</label><label><input type="radio" name="lesson-check" value="b"> Romans 1 continues into a larger argument in chapters 2–3.</label><label><input type="radio" name="lesson-check" value="c"> Romans 1 settles every modern ethical question without further interpretation.</label><button class="button secondary" data-action="lesson-check">Check reasoning</button>${state.lessonFeedback?`<div class="feedback">${esc(state.lessonFeedback)}</div>`:''}</div>`}
function lessonNav(){return LESSON_SCENES.map((s,i)=>`<button class="${i===state.scene?'active':''}" data-action="scene" data-index="${i}"><b>${i+1}. ${esc(s.role)}</b><br><span class="meta">${esc(s.title)}</span></button>`).join('')}
function lessonControls(){return `<div class="lesson-controls"><button class="button secondary" data-action="scene-prev" ${state.scene===0?'disabled':''}>← Previous</button><span class="scene-count">Scene ${state.scene+1} of ${LESSON_SCENES.length}</span><button class="button" data-action="scene-next" ${state.scene===LESSON_SCENES.length-1?'disabled':''}>Next →</button></div>`}
function renderLesson(){return state.direction==='A'?lessonA():state.direction==='B'?lessonB():lessonC()}
function lessonA(){const s=LESSON_SCENES[state.scene];return `<section class="page lesson-a"><aside class="panel lesson-rail"><p class="eyebrow">Unit 1 · Lesson 2</p><b>The Story and Its Setting</b><div class="scene-nav">${lessonNav()}</div></aside><article class="panel scene-stage"><p class="eyebrow">${esc(s.role)}</p><h1>${esc(s.title)}</h1><p class="lede">${esc(s.body)}</p><blockquote>${esc(s.aside)}</blockquote>${s.role==='Practice'?lessonCheck():''}${lessonControls()}</article><aside class="panel apparatus"><p class="eyebrow">Scholarly apparatus</p><details open><summary>Text / claim</summary><p class="meta">What the passage or lesson directly states.</p></details><details><summary>Historical context</summary><p class="meta">Audience, political world, language, social structures, and chronology.</p></details><details><summary>Interpretation</summary><p class="meta">How readers reason from text and context toward meaning.</p></details><details><summary>Sources</summary><p class="meta">Scripture, curriculum references, and vetted evidence stay identifiable.</p></details><button class="button secondary" data-page="theologian">Ask Theologian about this</button></aside></section>`}
function lessonB(){const s=LESSON_SCENES[state.scene];return `<section class="page lesson-b"><article class="folio-page"><p class="eyebrow">Unit 1 · Lesson 2 · ${esc(s.role)}</p><h1>${esc(s.title)}</h1><p class="main-copy">${esc(s.body)}</p><div class="divider"></div><p class="lede">${esc(s.aside)}</p>${s.role==='Practice'?lessonCheck():''}${lessonControls()}</article><aside class="folio-notes"><div class="folio-note"><b>In this lesson</b><p>Locate the claim, identify the setting, distinguish evidence from interpretation, then test your reasoning.</p></div><div class="folio-note"><b>Scene map</b><div class="scene-nav">${lessonNav()}</div></div><div class="folio-note"><b>Need another perspective?</b><button class="button secondary" data-page="theologian">Open Theologian</button></div></aside></section>`}
function lessonC(){const s=LESSON_SCENES[state.scene];return `<section class="page lesson-c"><article class="atlas-scene"><p class="eyebrow">Scene ${state.scene+1} · ${esc(s.role)}</p><h1>${esc(s.title)}</h1><p class="lede">${esc(s.body)}</p><div class="concept-map"><div class="concept-node"><b>Text</b><span class="meta">What is directly present?</span></div><div class="concept-node"><b>World</b><span class="meta">What historical assumptions matter?</span></div><div class="concept-node"><b>Meaning</b><span class="meta">What interpretive move connects them?</span></div></div>${s.role==='Practice'?lessonCheck():''}${lessonControls()}</article><aside class="atlas-side"><div class="panel"><p class="eyebrow">Scene path</p><div class="scene-nav">${lessonNav()}</div></div><div class="panel"><b>Context signal</b><p class="meta">${esc(s.aside)}</p></div><div class="panel"><b>Ask in context</b><button class="button" data-page="theologian">Ask Theologian</button></div></aside></section>`}

function renderPractice(){const item=PRACTICE_ITEMS[state.practiceIndex];return `<section class="page"><div class="section-head"><div><p class="eyebrow">Practice · active retention</p><h1 class="section-title">${esc(item.prompt)}</h1><p>Practice changes state only inside this prototype. Production scoring is not touched.</p></div><div class="chips"><span class="chip active">Recall</span><span class="chip">Relate</span><span class="chip">Interpret</span></div></div><div class="practice-layout"><article class="panel practice-main">${item.type==='order'?renderOrderPractice(item):renderDistinguishPractice(item)}${state.practiceFeedback?`<div class="feedback">${esc(state.practiceFeedback)}</div>`:''}</article><aside class="practice-side"><div class="panel"><p class="eyebrow">Retention</p><div class="retention-ring"><b>68%</b></div><p class="meta" style="text-align:center">Strengthening · review due now</p></div><div class="panel"><b>Why this matters</b><p class="meta">Retrieval, delayed review, transfer, and reasoning are visible outcomes—not just points.</p></div><div class="panel"><b>Next interval</b><p class="meta">If retained: 3 days → 7 → 14 → 30 → 60.</p></div></aside></div></section>`}
function renderOrderPractice(item){return `<p class="eyebrow">Ordering challenge · ${state.direction==='A'?'study table':state.direction==='B'?'structured retrieval':'timeline reconstruction'}</p><div class="order-list">${state.practiceOrder.map((x,i)=>`<div class="order-item"><span class="order-num">${i+1}</span><b>${esc(x)}</b><button class="move-btn" data-action="move-up" data-index="${i}" aria-label="Move ${esc(x)} up">↑</button><button class="move-btn" data-action="move-down" data-index="${i}" aria-label="Move ${esc(x)} down">↓</button></div>`).join('')}</div><div class="chips"><button class="button" data-action="practice-check">Check order</button><button class="button secondary" data-action="practice-next">Try interpretation challenge</button></div>`}
function renderDistinguishPractice(item){return `<p class="eyebrow">Evidence classification</p><div class="answer-options">${item.options.map(o=>`<button type="button" class="${state.practiceSelected===o?'selected':''}" data-action="practice-select" data-value="${esc(o)}">${esc(o)}</button>`).join('')}</div><div class="chips" style="margin-top:18px"><button class="button" data-action="practice-check">Check distinction</button><button class="button secondary" data-action="practice-next">Back to ordering</button></div>`}

function shelfMarkup(){return BOOK_GROUPS.map(g=>`<div class="shelf-group"><h3>${esc(g.name)}</h3><div class="book-shelf">${g.books.map(b=>`<button class="spine ${state.selectedBook===b?'active':''}" style="background:${g.color}" data-action="book" data-book="${esc(b)}">${esc(b)}</button>`).join('')}</div></div>`).join('')}
function bookInspector(){const d=bookDetails(state.selectedBook);const g=groupForBook(state.selectedBook);return `<p class="eyebrow">${esc(g?.name||'Book')}</p><h2>${esc(state.selectedBook)}</h2><p>${esc(d.subtitle)}</p><div class="divider"></div><p><b>Literary form</b><br><span class="meta">${esc(d.genre)}</span></p><p><b>Historical frame</b><br><span class="meta">${esc(d.era)}</span></p><p><b>Key content</b><br><span class="meta">${esc(d.key)}</span></p><p><b>Study question</b><br><span class="meta">${esc(d.question)}</span></p><div class="chips"><button class="button" data-page="lesson">Study a connected lesson</button><button class="button secondary" data-page="theologian">Ask Theologian</button></div>`}
function renderBible(){return state.direction==='A'?bibleA():state.direction==='B'?bibleB():bibleC()}
function bibleA(){return `<section class="page bible-a"><article class="panel shelf-stage"><div class="section-head"><div><p class="eyebrow">The Canonical Shelf</p><h1 class="section-title">Browse the library as a library.</h1></div><div class="chips"><span class="chip active">Shelf</span><span class="chip">Groups</span><span class="chip">Timeline</span></div></div>${shelfMarkup()}</article><aside class="panel book-inspector">${bookInspector()}</aside></section>`}
function bibleB(){const rows=BOOK_GROUPS.flatMap(g=>g.books.map((b,i)=>({b,g,index:i})));return `<section class="page bible-b"><article><div class="section-head"><div><p class="eyebrow">Bible reference</p><h1 class="section-title">66 books, organized for study.</h1></div></div><table class="catalog-table"><thead><tr><th>Book</th><th>Group</th><th>Reference mode</th></tr></thead><tbody>${rows.map(({b,g})=>`<tr class="${state.selectedBook===b?'active':''}"><td><button data-action="book" data-book="${esc(b)}">${esc(b)}</button></td><td>${esc(g.name)}</td><td class="meta">Profile · chapters · context</td></tr>`).join('')}</tbody></table></article><aside class="panel book-inspector">${bookInspector()}</aside></section>`}
function bibleC(){return `<section class="page bible-c"><article class="panel atlas-books"><div class="section-head"><div><p class="eyebrow">Scripture Atlas</p><h1 class="section-title">Move between canon, chronology, and relationship.</h1></div><div class="chips"><span class="chip active">Canon</span><span class="chip">Chronology</span><span class="chip">Map</span></div></div><div class="constellation">${BOOK_GROUPS.flatMap(g=>g.books.map(b=>`<button class="book-node ${state.selectedBook===b?'active':''}" data-action="book" data-book="${esc(b)}"><b>${esc(b)}</b><small>${esc(g.name)}</small></button>`)).join('')}</div></article><aside class="panel book-inspector">${bookInspector()}</aside></section>`}

function currentTopic(){return TOPICS.find(t=>t.id===state.topic)||TOPICS[0]}
function topicArticle(t){return `<p class="eyebrow">${esc(t.category)}</p><h1>${esc(t.title)}</h1><p class="lede">${esc(t.summary)}</p><div class="divider"></div><h3>Study pathways</h3><p>Begin with the biblical texts themselves, then separate historical evidence, interpretive arguments, reception history, doctrinal synthesis, and application.</p><div class="topic-links">${t.links.map(x=>`<span>${esc(x)}</span>`).join('')}</div><p class="meta">Connected course: ${esc(t.course)}</p><div class="chips"><button class="button" data-page="bible">Open Scripture</button><button class="button secondary" data-page="theologian">Ask Theologian</button></div>`}
function renderTopics(){const t=currentTopic();return state.direction==='A'?topicsA(t):state.direction==='B'?topicsB(t):topicsC(t)}
function topicsA(t){return `<section class="page topics-a"><aside class="panel catalog-drawers"><p class="eyebrow">Card catalog · 45 Topics</p>${TOPICS.map(x=>`<button class="${x.id===t.id?'active':''}" data-action="topic" data-topic="${x.id}"><b>${esc(x.title)}</b><br><span class="meta">${esc(x.category)}</span></button>`).join('')}</aside><article class="panel topic-article">${topicArticle(t)}</article></section>`}
function topicsB(t){return `<section class="page topics-b"><div class="section-head"><div><p class="eyebrow">Curated reference</p><h1 class="section-title">Topics are for exploration, not completion.</h1></div><p>Browse questions and concepts without turning reference reading into a second curriculum.</p></div><div class="topic-index">${TOPICS.map(x=>`<button class="${x.id===t.id?'active':''}" data-action="topic" data-topic="${x.id}"><b>${esc(x.title)}</b><p class="meta">${esc(x.summary)}</p></button>`).join('')}</div><article class="journal-article">${topicArticle(t)}</article></section>`}
function topicsC(t){return `<section class="page topics-c"><article class="topic-map"><p class="eyebrow">Relationship map</p><h1 class="section-title">Follow an idea across Scripture.</h1><div class="topic-map-grid">${TOPICS.map(x=>`<button class="topic-orb ${x.id===t.id?'active':''}" data-action="topic" data-topic="${x.id}"><span><b>${esc(x.title)}</b><br><small>${esc(x.category)}</small></span></button>`).join('')}</div></article><aside class="panel topic-article">${topicArticle(t)}</aside></section>`}

function classifyTheologian(q){const low=q.toLowerCase();return THEOLOGIAN_DEMOS.find(d=>d.match.some(m=>low.includes(m)))||DEFAULT_THEOLOGIAN}
function theologianRail(result){if(!result)return `<div class="panel"><p class="eyebrow">Evidence workspace</p><h3>Nothing selected yet.</h3><p class="meta">Submit a question to see how sources, interpretations, limits, and follow-ups are separated.</p></div>`;return `<div class="panel"><p class="eyebrow">Evidence used</p>${result.evidence.map(([type,text])=>`<div class="evidence-item"><b>${esc(type)}</b><span>${esc(text)}</span></div>`).join('')}</div><div class="panel"><p class="eyebrow">Limits</p><p>${esc(result.limits)}</p></div><div class="panel"><p class="eyebrow">Continue exploring</p><div class="follow-ups">${result.follow.map(x=>`<button data-action="theologian-follow" data-question="${esc(x)}">${esc(x)} →</button>`).join('')}</div></div>`}
function renderTheologian(){const cls=state.direction==='A'?'theologian-a':state.direction==='B'?'theologian-b':'theologian-c';const intro=state.direction==='A'?'Consult the library without surrendering the sources.':state.direction==='B'?'Ask a question. Inspect the evidence. Compare interpretations.':'Ask from wherever you are in the biblical world.';return `<section class="page ${cls}"><div class="theologian-layout"><article class="panel theologian-chat"><div class="theologian-head"><p class="eyebrow">Theologian · ${directionName()}</p><h1>Theologian</h1><p>${intro}</p><div class="theologian-status"><b>Interactive prototype:</b> question submission works. Responses are deterministic demo synthesis; no remote model is connected.</div></div><div class="suggestions"><button data-action="suggest" data-question="What does Romans 1 say about same-sex relationships?">Romans 1</button><button data-action="suggest" data-question="Were Ruth and Naomi a couple?">Ruth & Naomi</button><button data-action="suggest" data-question="How does Canonical Shelf understand salvation and grace?">Salvation</button></div><div class="chat-log" aria-live="polite">${state.chat.length?state.chat.map(m=>`<div class="message ${m.role}"><span class="label">${m.role==='user'?'You':'Theologian'}</span>${esc(m.text)}</div>`).join(''):`<div class="empty-note">Ask a question above or use one of the suggested prompts. The prototype will show the complete answer structure rather than a non-functional “Guide” shell.</div>`}</div><form class="ask-form" id="theologian-form"><label class="sr-only" for="theologian-q">Ask the Theologian</label><textarea id="theologian-q" name="question" placeholder="Ask about a passage, doctrine, historical context, interpretation, or Christian tradition…">${esc(state.theologianQuestion)}</textarea><button class="button" type="submit">Ask</button></form></article><aside class="evidence-rail">${theologianRail(state.theologianResult)}</aside></div></section>`}

function moveOrder(index,delta){const next=[...state.practiceOrder];const target=index+delta;if(target<0||target>=next.length)return;[next[index],next[target]]=[next[target],next[index]];setState({practiceOrder:next,practiceFeedback:''})}
function checkPractice(){const item=PRACTICE_ITEMS[state.practiceIndex];if(item.type==='order'){const ok=item.answer.every((x,i)=>x===state.practiceOrder[i]);setState({practiceFeedback:ok?'Correct. You reconstructed the sequence. In production, this would update retention strength and review timing.':'Not yet. Reconsider the relationship between Abraham, Exodus, Sinai, and the wilderness journey.'})}else{const ok=state.practiceSelected===item.answer;setState({practiceFeedback:ok?'Correct. That statement goes beyond direct observation and makes an interpretive claim about modern application.':'Try again. Look for the option that moves furthest beyond what the passage directly states.'})}}
function askTheologian(q){const question=String(q||'').trim();if(!question)return;const result=classifyTheologian(question);const chat=[...state.chat,{role:'user',text:question},{role:'assistant',text:result.answer}];state={...state,theologianQuestion:'',theologianResult:result,chat};saveState();render()}

window.addEventListener('click',e=>{
  const target=e.target.closest('button');if(!target)return;
  if(target.dataset.page){setState({page:target.dataset.page});return}
  if(target.dataset.directionChoice){setState({direction:target.dataset.directionChoice});return}
  const action=target.dataset.action;
  if(action==='scene')setState({scene:Number(target.dataset.index),lessonFeedback:''});
  if(action==='scene-prev')setState({scene:Math.max(0,state.scene-1),lessonFeedback:''});
  if(action==='scene-next')setState({scene:Math.min(LESSON_SCENES.length-1,state.scene+1),lessonFeedback:''});
  if(action==='lesson-check'){const checked=document.querySelector('input[name="lesson-check"]:checked');setState({lessonFeedback:checked?.value==='c'?'Correct. That sentence is an interpretive/application claim, not direct textual observation.':'Not quite. Two options describe observable features of the text or its literary context; one claims a complete modern application.'})}
  if(action==='move-up')moveOrder(Number(target.dataset.index),-1);
  if(action==='move-down')moveOrder(Number(target.dataset.index),1);
  if(action==='practice-select')setState({practiceSelected:target.dataset.value,practiceFeedback:''});
  if(action==='practice-check')checkPractice();
  if(action==='practice-next')setState({practiceIndex:state.practiceIndex===0?1:0,practiceFeedback:'',practiceSelected:'',practiceOrder:[...PRACTICE_ITEMS[0].options]});
  if(action==='book')setState({selectedBook:target.dataset.book});
  if(action==='topic')setState({topic:target.dataset.topic});
  if(action==='suggest'){const q=target.dataset.question;state.theologianQuestion=q;saveState();render();requestAnimationFrame(()=>document.querySelector('#theologian-q')?.focus())}
  if(action==='theologian-follow'){const q=target.dataset.question;askTheologian(q)}
});

document.addEventListener('submit',e=>{if(e.target.id==='theologian-form'){e.preventDefault();askTheologian(new FormData(e.target).get('question'))}});
document.querySelector('#reset-demo').addEventListener('click',()=>{state={...defaultState,practiceOrder:[...PRACTICE_ITEMS[0].options],chat:[]};saveState();render()});

render();